vim.keymap.set('n', '<leader>dB', function()
  require('dap').set_breakpoint(vim.fn.input('Condition: '))
end)

vim.keymap.set('n', '<leader>dl', function()
  require('dap').set_breakpoint(nil, nil, vim.fn.input('Log: '))
end)

dap.adapters['pwa-node'] = {
  type = 'server',
  host = 'localhost',
  port = '${port}',
  executable = {
    command = 'node',
    args = { vim.fn.stdpath('data') .. '/mason/packages/js-debug-adapter/js-debug/src/dapDebugServer.js', '${port}' },
  },
}

require('nvim-dap-virtual-text').setup({
  commented = true,
  virt_text_pos = 'eol',
  all_frames = true,
  highlight_changed_variables = true,
})

require('dap-go').setup({
  delve = {
    path = vim.fn.stdpath('data') .. '/mason/packages/delve/dlv',
  },
})

vim.keymap.set('n', '<leader>dgt', require('dap-go').debug_test)

require('mason-nvim-dap').setup({
  ensure_installed = { 'codelldb', 'debugpy', 'js-debug-adapter' },
  automatic_installation = true,
  handlers = {
    function(config)
      require('mason-nvim-dap').default_setup(config)
    end,
    python = function(config)
      config.configurations = {{
        type = 'python',
        request = 'launch',
        name = 'Launch file',
        program = '${file}',
      }}
      require('mason-nvim-dap').default_setup(config)
    end,
  },
})
